<template>
  <div class="page">
    <div class="head"><div><h2>体系合规管理</h2><p>质量目标、内审、不良事件、顾客反馈与合规预警</p></div><el-space><el-button @click="exportDashboard">导出看板</el-button><el-button @click="load">刷新看板</el-button></el-space></div>
    <el-row :gutter="14" class="cards"><el-col v-for="key in metricKeys" :key="key" :span="4"><el-card><span>{{ labels[key] || key }}</span><b :class="{danger:key!=='healthScore'&&Number(dashboard[key])>0}">{{ dashboard[key]??0 }}{{key==='auditCompletionRate'?'%':''}}</b></el-card></el-col></el-row>
    <el-row :gutter="14" class="charts"><el-col :span="12"><el-card><div ref="healthEl" class="chart"/></el-card></el-col><el-col :span="12"><el-card><div ref="trendEl" class="chart"/></el-card></el-col></el-row>
    <el-card class="warning-card"><template #header><b>合规预警中心（{{dashboard.warnings?.length||0}}）</b></template><el-table :data="dashboard.warnings||[]" max-height="260"><el-table-column prop="type" label="预警类型"/><el-table-column prop="title" label="事项" show-overflow-tooltip/><el-table-column prop="dueDate" label="期限"/><el-table-column label="操作" width="90"><template #default="{row}"><el-button link type="primary" @click="drill(row)">处理</el-button></template></el-table-column></el-table></el-card>
    <el-card>
      <el-tabs v-model="tab">
        <el-tab-pane label="质量目标" name="objectives"><el-button type="primary" @click="open('objective')">新增目标</el-button><el-table :data="objectives"><el-table-column prop="objectiveName" label="目标"/><el-table-column prop="periodType" label="周期"/><el-table-column prop="responsibleDepartment" label="责任部门"/><el-table-column prop="targetValue" label="目标值"/><el-table-column prop="actualValue" label="实际值"/><el-table-column prop="status" label="状态"/><el-table-column label="操作"><template #default="{row}"><el-button link @click="open('objective',row)">编辑</el-button></template></el-table-column></el-table></el-tab-pane>
        <el-tab-pane label="内审计划" name="audits"><el-button type="primary" @click="open('audit')">新增计划</el-button><el-table :data="audits"><el-table-column prop="auditYear" label="年度"/><el-table-column prop="auditScope" label="审核范围"/><el-table-column prop="auditBasis" label="审核依据"/><el-table-column prop="plannedDate" label="计划日期"/><el-table-column prop="status" label="状态"/><el-table-column label="操作" width="190"><template #default="{row}"><el-button link @click="open('audit',row)">编辑</el-button><el-button v-if="nextAudit(row.status)" link type="primary" @click="advanceAudit(row)">{{nextAudit(row.status)}}</el-button></template></el-table-column></el-table></el-tab-pane>
        <el-tab-pane label="不符合项" name="nc"><el-button type="primary" @click="open('nc')">新增不符合项</el-button><el-table :data="nonconformities"><el-table-column prop="description" label="描述" min-width="180"/><el-table-column prop="clauseReference" label="条款"/><el-table-column prop="severity" label="严重程度"/><el-table-column prop="responsibleDepartment" label="责任部门"/><el-table-column prop="dueDate" label="整改期限"/><el-table-column prop="capaNo" label="CAPA编号"/><el-table-column prop="status" label="状态"/><el-table-column label="操作" width="220"><template #default="{row}"><el-button link @click="open('nc',row)">编辑</el-button><el-button v-if="!row.capaNo" link type="warning" @click="startCapa('nonconformities',row)">发起CAPA</el-button><el-button v-if="row.status!=='已关闭'" link type="primary" @click="openCloseNc(row)">验证关闭</el-button></template></el-table-column></el-table></el-tab-pane>
        <el-tab-pane label="不良事件" name="events"><el-button type="primary" @click="open('event')">新增事件</el-button><el-table :data="events"><el-table-column prop="eventDate" label="发生时间"/><el-table-column prop="productName" label="产品"/><el-table-column prop="productBatchNo" label="批次"/><el-table-column prop="harmLevel" label="伤害等级"/><el-table-column prop="reportDate" label="上报日期"/><el-table-column prop="capaNo" label="CAPA编号"/><el-table-column prop="status" label="状态"/><el-table-column label="操作" width="160"><template #default="{row}"><el-button link @click="open('event',row)">评估/处理</el-button><el-button v-if="!row.capaNo" link type="warning" @click="startCapa('events',row)">发起CAPA</el-button></template></el-table-column></el-table></el-tab-pane>
        <el-tab-pane label="顾客反馈" name="feedback"><el-button type="primary" @click="open('feedback')">新增反馈</el-button><el-table :data="feedback"><el-table-column prop="feedbackType" label="类型"/><el-table-column prop="customerName" label="客户"/><el-table-column prop="category" label="分类"/><el-table-column prop="responsibleDepartment" label="责任部门"/><el-table-column prop="dueDate" label="处理期限"/><el-table-column prop="capaNo" label="CAPA编号"/><el-table-column prop="status" label="状态"/><el-table-column label="操作" width="220"><template #default="{row}"><el-button link @click="open('feedback',row)">编辑</el-button><el-button v-if="!row.capaNo" link type="warning" @click="startCapa('feedback',row)">发起CAPA</el-button><el-button v-if="row.status!=='已关闭'" link type="primary" @click="openCloseFeedback(row)">处理关闭</el-button></template></el-table-column></el-table></el-tab-pane>
      </el-tabs>
    </el-card>
    <el-dialog v-model="editorVisible" :title="editingId?'编辑记录':titles[mode]" width="650px"><el-form :model="form" label-width="100px"><template v-if="mode==='objective'"><el-form-item label="目标名称"><el-input v-model="form.objectiveName"/></el-form-item><el-form-item label="上级目标"><el-select v-model="form.parentId" clearable><el-option v-for="o in objectives" :key="o.id" :label="o.objectiveName" :value="o.id"/></el-select></el-form-item><el-form-item label="周期"><el-select v-model="form.periodType"><el-option label="月" value="月"/><el-option label="季" value="季"/><el-option label="年" value="年"/></el-select></el-form-item><el-form-item label="责任部门"><el-input v-model="form.responsibleDepartment"/></el-form-item><el-form-item label="目标值"><el-input-number v-model="form.targetValue"/></el-form-item><el-form-item label="实际值"><el-input-number v-model="form.actualValue"/></el-form-item></template><template v-else-if="mode==='audit'"><el-form-item label="年度"><el-input-number v-model="form.auditYear"/></el-form-item><el-form-item label="审核范围"><el-input v-model="form.auditScope" type="textarea"/></el-form-item><el-form-item label="审核依据"><el-input v-model="form.auditBasis"/></el-form-item><el-form-item label="审核组"><el-input v-model="form.auditorGroup"/></el-form-item><el-form-item label="计划日期"><el-date-picker v-model="form.plannedDate" value-format="YYYY-MM-DD"/></el-form-item><el-form-item label="实施总结"><el-input v-model="form.implementationSummary" type="textarea"/></el-form-item></template><template v-else-if="mode==='nc'"><el-form-item label="内审计划"><el-select v-model="form.auditPlanId"><el-option v-for="a in audits" :key="a.id" :label="`${a.auditYear}-${a.auditScope}`" :value="a.id"/></el-select></el-form-item><el-form-item label="不符合描述"><el-input v-model="form.description" type="textarea"/></el-form-item><el-form-item label="条款依据"><el-input v-model="form.clauseReference"/></el-form-item><el-form-item label="严重程度"><el-select v-model="form.severity"><el-option label="严重" value="严重"/><el-option label="一般" value="一般"/><el-option label="观察项" value="观察项"/></el-select></el-form-item><el-form-item label="责任部门"><el-input v-model="form.responsibleDepartment"/></el-form-item><el-form-item label="整改期限"><el-date-picker v-model="form.dueDate" value-format="YYYY-MM-DD"/></el-form-item><el-form-item label="CAPA编号"><el-input v-model="form.capaNo"/></el-form-item></template><template v-else-if="mode==='event'"><el-form-item label="发生时间"><el-date-picker v-model="form.eventDate" type="datetime" value-format="YYYY-MM-DDTHH:mm:ss"/></el-form-item><el-form-item label="产品"><el-input v-model="form.productName"/></el-form-item><el-form-item label="产品批次"><el-input v-model="form.productBatchNo"/></el-form-item><el-form-item label="事件描述"><el-input v-model="form.eventDescription" type="textarea"/></el-form-item><el-form-item label="伤害等级"><el-select v-model="form.harmLevel"><el-option label="死亡" value="死亡"/><el-option label="严重伤害" value="严重伤害"/><el-option label="其他" value="其他"/></el-select></el-form-item><el-form-item label="评估结论"><el-input v-model="form.assessmentResult" type="textarea"/></el-form-item><el-form-item label="上报期限"><el-date-picker v-model="form.reportDeadline" value-format="YYYY-MM-DD"/></el-form-item><el-form-item label="上报日期"><el-date-picker v-model="form.reportDate" value-format="YYYY-MM-DD"/></el-form-item><el-form-item label="上报回执"><el-input v-model="form.reportReceiptNo"/></el-form-item><el-form-item label="根本原因"><el-input v-model="form.rootCause" type="textarea"/></el-form-item><el-form-item label="纠正措施"><el-input v-model="form.correctiveAction" type="textarea"/></el-form-item><el-form-item label="CAPA编号"><el-input v-model="form.capaNo"/></el-form-item></template><template v-else><el-form-item label="反馈类型"><el-select v-model="form.feedbackType"><el-option label="投诉" value="投诉"/><el-option label="建议" value="建议"/><el-option label="咨询" value="咨询"/></el-select></el-form-item><el-form-item label="客户"><el-input v-model="form.customerName"/></el-form-item><el-form-item label="反馈内容"><el-input v-model="form.content" type="textarea"/></el-form-item><el-form-item label="分类"><el-input v-model="form.category"/></el-form-item><el-form-item label="责任部门"><el-input v-model="form.responsibleDepartment"/></el-form-item><el-form-item label="处理期限"><el-date-picker v-model="form.dueDate" value-format="YYYY-MM-DD"/></el-form-item><el-form-item label="售后工单ID"><el-input-number v-model="form.afterSalesOrderId"/></el-form-item><el-form-item label="CAPA编号"><el-input v-model="form.capaNo"/></el-form-item></template></el-form><template #footer><el-button @click="editorVisible=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog>
    <el-dialog v-model="closeVisible" :title="mode==='closeNc'?'验证关闭不符合项':'关闭顾客反馈'" width="520px"><el-form :model="form" label-width="100px"><template v-if="mode==='closeNc'"><el-form-item label="整改措施"><el-input v-model="form.rectificationMeasure" type="textarea"/></el-form-item><el-form-item label="验证结论"><el-input v-model="form.verificationResult" type="textarea"/></el-form-item></template><template v-else><el-form-item label="调查过程"><el-input v-model="form.investigation" type="textarea"/></el-form-item><el-form-item label="处理措施"><el-input v-model="form.handlingMeasure" type="textarea"/></el-form-item><el-form-item label="客户回复"><el-input v-model="form.customerReply" type="textarea"/></el-form-item></template></el-form><template #footer><el-button @click="closeVisible=false">取消</el-button><el-button type="primary" @click="submitClose">确认关闭</el-button></template></el-dialog>
  </div>
</template>
<script setup lang="ts">
import{nextTick,onBeforeUnmount,onMounted,reactive,ref}from'vue';import{ElMessage,ElMessageBox}from'element-plus';import*as echarts from'echarts';import{closeFeedback,closeNonconformity,createAudit,createEvent,createFeedback,createNonconformity,createObjective,createQualityCapa,getAudits,getEvents,getFeedback,getNonconformities,getObjectives,getQualityDashboard,transitionAudit,updateAudit,updateEvent,updateFeedback,updateNonconformity,updateObjective}from'@/api/qualitySystem';
const tab=ref('objectives'),dashboard=ref<Record<string,any>>({}),objectives=ref<any[]>([]),audits=ref<any[]>([]),nonconformities=ref<any[]>([]),events=ref<any[]>([]),feedback=ref<any[]>([]),editorVisible=ref(false),closeVisible=ref(false),mode=ref(''),selectedId=ref<number>(),editingId=ref<number>(),healthEl=ref<HTMLElement>(),trendEl=ref<HTMLElement>();let healthChart:echarts.ECharts|undefined,trendChart:echarts.ECharts|undefined;const form=reactive<Record<string,any>>({});const metricKeys=['healthScore','objectiveTotal','underTarget','openNonconformities','openEvents','openFeedback'];const labels:Record<string,string>={healthScore:'体系健康度',objectiveTotal:'质量目标',underTarget:'未达标目标',openNonconformities:'未关闭不符合项',openEvents:'待处理事件',openFeedback:'待处理反馈'};const titles:Record<string,string>={objective:'新增质量目标',audit:'新增内审计划',nc:'新增不符合项',event:'新增不良事件',feedback:'新增顾客反馈'};
async function load(){const[a,b,c,d,e,f]=await Promise.all([getQualityDashboard(),getObjectives(),getAudits(),getNonconformities(),getEvents(),getFeedback()]);dashboard.value=a.data||{};objectives.value=b.data||[];audits.value=c.data||[];nonconformities.value=d.data||[];events.value=e.data||[];feedback.value=f.data||[];await nextTick();renderCharts()}
function reset(){Object.keys(form).forEach(k=>delete form[k])}function open(x:string,row?:any){mode.value=x;editingId.value=row?.id;reset();Object.assign(form,row|| (x==='objective'?{periodType:'月',targetValue:100}:x==='audit'?{auditYear:new Date().getFullYear()}:x==='nc'?{severity:'一般'}:x==='event'?{eventDate:new Date().toISOString().slice(0,19),harmLevel:'其他'}:{feedbackType:'投诉',feedbackDate:new Date().toISOString().slice(0,10)}));editorVisible.value=true}
async function save(){const id=editingId.value;if(mode.value==='objective')id?await updateObjective(id,form):await createObjective(form);else if(mode.value==='audit')id?await updateAudit(id,form):await createAudit(form);else if(mode.value==='nc')id?await updateNonconformity(id,form):await createNonconformity(form);else if(mode.value==='event')id?await updateEvent(id,form):await createEvent(form);else id?await updateFeedback(id,form):await createFeedback(form);editorVisible.value=false;ElMessage.success('保存成功');load()}
function openCloseNc(row:any){mode.value='closeNc';selectedId.value=row.id;reset();form.rectificationMeasure=row.rectificationMeasure||'';closeVisible.value=true}function openCloseFeedback(row:any){mode.value='closeFeedback';selectedId.value=row.id;reset();closeVisible.value=true}async function submitClose(){if(!selectedId.value)return;if(mode.value==='closeNc')await closeNonconformity(selectedId.value,form);else await closeFeedback(selectedId.value,form);closeVisible.value=false;ElMessage.success('已关闭');load()}
function nextAudit(status:string){return({草稿:'提交审批',待审批:'批准',已批准:'开始实施',实施中:'完成'}as Record<string,string>)[status]}async function advanceAudit(row:any){let status=({草稿:'待审批',待审批:'已批准',已批准:'实施中',实施中:'已完成'}as Record<string,string>)[row.status];if(!status)return;let data:any=undefined;if(status==='已完成'){const{value}=await ElMessageBox.prompt('请输入内审实施总结','完成内审',{inputType:'textarea',inputValue:row.implementationSummary||''});data={implementationSummary:value}}await transitionAudit(row.id,status,data);ElMessage.success(`内审计划已更新为${status}`);load()}
async function startCapa(kind:'nonconformities'|'events'|'feedback',row:any){const r=await createQualityCapa(kind,row.id);ElMessage.success(`CAPA ${r.data?.capaNo||''} 已创建并回写`);load()}
function drill(row:any){tab.value=row.tab==='measurement'?'objectives':row.tab;ElMessage.info(row.tab==='measurement'?'请到“计量”模块处理该预警':'已定位到对应业务页签')}
function renderCharts(){const score=Number(dashboard.value.healthScore||0);healthChart=healthChart||echarts.init(healthEl.value!);healthChart.setOption({title:{text:'体系运行健康度',left:'center',textStyle:{fontSize:15}},series:[{type:'gauge',startAngle:200,endAngle:-20,min:0,max:100,progress:{show:true,width:14},axisLine:{lineStyle:{width:14}},detail:{formatter:'{value} 分',fontSize:22},data:[{value:score}]}]});const e=dashboard.value.eventTrend||{},f=dashboard.value.feedbackTrend||{},months=Array.from(new Set([...Object.keys(e),...Object.keys(f)])).sort();trendChart=trendChart||echarts.init(trendEl.value!);trendChart.setOption({title:{text:'不良事件 / 顾客反馈趋势',textStyle:{fontSize:15}},tooltip:{trigger:'axis'},legend:{data:['不良事件','顾客反馈']},xAxis:{type:'category',data:months},yAxis:{type:'value',minInterval:1},series:[{name:'不良事件',type:'line',data:months.map(x=>e[x]||0)},{name:'顾客反馈',type:'line',data:months.map(x=>f[x]||0)}]})}
function exportDashboard(){const rows=[['指标','数值'],...metricKeys.map(k=>[labels[k],dashboard.value[k]??0]),['内审完成率',dashboard.value.auditCompletionRate??0],['CAPA关联数',dashboard.value.capaLinked??0],[],['预警类型','事项','期限'],...(dashboard.value.warnings||[]).map((x:any)=>[x.type,x.title,x.dueDate])];const blob=new Blob(['\ufeff'+rows.map(r=>r.map((v:any)=>`"${String(v??'').replace(/"/g,'""')}"`).join(',')).join('\n')],{type:'text/csv;charset=utf-8'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`体系运行看板-${new Date().toISOString().slice(0,10)}.csv`;a.click();URL.revokeObjectURL(a.href)}
onBeforeUnmount(()=>{healthChart?.dispose();trendChart?.dispose()});onMounted(load)
</script>
<style scoped>.page{padding:20px}.head{display:flex;justify-content:space-between;align-items:center;margin-bottom:16px}.head h2{margin:0;color:#1b3a5b}.head p{margin:6px 0 0;color:#8c9ba8}.cards,.charts,.warning-card{margin-bottom:16px}.cards span{font-size:12px;color:#8c9ba8}.cards b{display:block;font-size:24px;color:#1b3a5b;margin-top:8px}.cards b.danger{color:#c2413a}.chart{height:270px}.el-tab-pane>.el-button{margin-bottom:12px}</style>
